import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Bounds {
    static double sum(List<? extends Number> xs) {        // producer: we only read.
        double total = 0;
        for (Number n : xs) total += n.doubleValue();
        return total;
    }

    static void addSquares(List<? super Integer> out, int n) {   // consumer: we only add.
        for (int i = 1; i <= n; i++) out.add(i * i);
    }

    static <T extends Comparable<T>> T max(List<T> xs) {  // one T in two positions.
        return Collections.max(xs);
    }

    public static void main(String[] args) {
        System.out.println(sum(List.of(1, 2, 3)));        // 6.0
        System.out.println(sum(List.of(1.5, 2.5)));        // 4.0
        List<Number> nums = new ArrayList<>();
        addSquares(nums, 3);
        System.out.println(nums);                          // [1, 4, 9]
        System.out.println(max(List.of("pear", "apple")));   // pear
    }
}
```

| Need | Signature |
|---|---|
| read items as Number. | List<? extends Number>. |
| add Integers. | List<? super Integer>. |
| relate input and output types. | <T extends Bound>. |

